class Widget {
public:
  using DataType = std::vector<double>;

  // Overload for lvalue Widgets: returns a modifiable reference
  DataType& data() & {
    // ... logging or other logic ...
    return values;
  }

  // Overload for rvalue Widgets: moves the data out
  DataType data() && {
    // ... logging or other logic ...
    return std::move(values);
  }

private:
  DataType values;
};

Widget makeWidget() { return Widget(); }

// Usage:
Widget w;
auto val1 = w.data();             // Calls lvalue overload, copies data
auto val2 = makeWidget().data();  // Calls rvalue overload, moves data
